'use strict';
const DATA=JSON.parse(document.getElementById('bookData').textContent);
const ASSETS=JSON.parse(document.getElementById('pageAssets').textContent);
const LINKS=JSON.parse(document.getElementById('bookLinks').textContent);
const $=id=>document.getElementById(id);
const imgSrc=p=>ASSETS[p-1];
const TOTAL=DATA.total, KEY='naiwa-reader-v1';
const media=matchMedia('(max-width:760px)'), reduced=matchMedia('(prefers-reduced-motion:reduce)');
let stored={};try{stored=JSON.parse(localStorage.getItem(KEY)||'{}')||{};}catch{}
let current=Math.max(1,Math.min(TOTAL,Number(stored.page)||1));
let savedPage=current, reading=false, mode='flip', turning=false, pendingTurn=null, scrollBuilt=false, scrollLock=false, scrollRaf=0, resizeRaf=0;
let bookmarks=new Set(Array.isArray(stored.bookmarks)?stored.bookmarks.filter(p=>Number.isInteger(p)&&p>=1&&p<=TOTAL):[]);
let zoomPage=1, zoomScale=1, toastTimer=0;
const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const normalizePage=n=>Math.max(1,Math.min(TOTAL,Math.round(Number(n)||1)));
const spreadStart=n=>(media.matches||n===1)?n:n-(n%2);
function visiblePages(p=current){if(media.matches||p===1)return[p];const start=spreadStart(p);return start+1<=TOTAL?[start,start+1]:[start];}
function chapterFor(p){return DATA.toc.filter(t=>t.depth===0&&t.page<=p).at(-1)?.title||'封面';}
function save(){if(reading)savedPage=current;try{localStorage.setItem(KEY,JSON.stringify({page:savedPage,bookmarks:[...bookmarks].sort((a,b)=>a-b)}));}catch{}}
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),2200);}
function updateCover(){if(savedPage>1){$('startBtn').querySelector('span').textContent='继续阅读';$('resumeNote').textContent=`上次读到第 ${savedPage} 页 · ${chapterFor(savedPage)}`;}else{$('startBtn').querySelector('span').textContent='翻开这本书';}}
function updateMeta(){const pages=mode==='scroll'?[current]:visiblePages();$('pageRange').textContent=`第 ${pages.join('–')} 页 / 共 ${TOTAL} 页`;$('chapterCurrent').textContent=chapterFor(current);$('pageInput').value=current;$('progress').value=current;$('progress').setAttribute('aria-valuetext',`第 ${current} 页，共 ${TOTAL} 页`);$('percent').textContent=Math.round(current/TOTAL*100)+'%';$('prevBtn').disabled=current<=1;$('nextBtn').disabled=pages.at(-1)>=TOTAL;const marked=bookmarks.has(current);$('markBtn').classList.toggle('bookmark-active',marked);$('markBtn').setAttribute('aria-pressed',String(marked));$('markBtn').setAttribute('aria-label',marked?'移除当前页书签':'添加当前页书签');$('markBtn').title=marked?'移除当前页书签':'添加当前页书签';$('readRibbon').hidden=!marked;$('drawerMarkBtn').textContent=marked?`移除第 ${current} 页书签`:`为第 ${current} 页添加书签`;document.querySelectorAll('.toc-item[data-page]').forEach(b=>b.classList.toggle('current',Number(b.dataset.page)===current));}
function addLinks(el,p){for(const link of LINKS[p]||[]){const a=document.createElement('a');a.className='pdf-link';a.href='#page='+link.targetPage;a.style.cssText=`left:${link.x*100}%;top:${link.y*100}%;width:${link.w*100}%;height:${link.h*100}%;min-height:6px`;a.setAttribute('aria-label',`跳转至第 ${link.targetPage} 页`);a.addEventListener('click',event=>{event.preventDefault();event.stopPropagation();navigate(link.targetPage,false);});el.append(a);}}
function pageElement(p,side=''){const page=document.createElement('div');page.className='book-page '+side;page.dataset.page=p;const img=document.createElement('img');img.src=imgSrc(p);img.alt=`《奶蛙学》第 ${p} 页 · ${chapterFor(p)}`;img.width=1429;img.height=2021;img.draggable=false;page.append(img);const text=document.createElement('div');text.className='sr-only';text.textContent=DATA.texts[p-1]||'';page.append(text);addLinks(page,p);page.addEventListener('click',()=>{if(!turning&&!suppressClick)openZoom(p);});return page;}
function fitBook(){if(!reading||mode!=='flip')return;const stage=$('bookStage');const styles=getComputedStyle(stage);const availW=stage.clientWidth-parseFloat(styles.paddingLeft)-parseFloat(styles.paddingRight),availH=stage.clientHeight-parseFloat(styles.paddingTop)-parseFloat(styles.paddingBottom);const count=visiblePages().length;const ratio=1429/2021*count;const h=Math.max(100,Math.min(availH,availW/ratio,900));$('book').style.setProperty('--book-h',h+'px');$('book').style.setProperty('--book-w',h*ratio+'px');}
function renderSpread(){const pages=visiblePages();$('book').classList.toggle('single',pages.length===1);$('spread').replaceChildren(...pages.map((p,i)=>pageElement(p,i===0&&pages.length===2?'left':'right')));fitBook();updateMeta();}
function setHash(){try{history.replaceState(null,'','#page='+current);}catch{}}
async function flipTo(target){if(turning)return;const oldPages=visiblePages();const nextPages=visiblePages(target);if(reduced.matches||oldPages.length!==nextPages.length){current=target;renderSpread();save();setHash();return;}
turning=true;const forward=target>current;
if(oldPages.length===1){const oldLeaf=$('spread').firstElementChild;oldLeaf.style.transformOrigin=forward?'left center':'right center';const fade=oldLeaf.animate([{transform:'rotateY(0deg)',opacity:1},{transform:`rotateY(${forward?-55:55}deg)`,opacity:0}],{duration:240,easing:'ease-in',fill:'forwards'});try{await fade.finished;}catch{}current=target;renderSpread();const newLeaf=$('spread').firstElementChild;newLeaf.style.transformOrigin=forward?'right center':'left center';const reveal=newLeaf.animate([{transform:`rotateY(${forward?35:-35}deg)`,opacity:0},{transform:'rotateY(0deg)',opacity:1}],{duration:260,easing:'ease-out'});try{await reveal.finished;}catch{}turning=false;save();setHash();if(pendingTurn!==null){const queued=pendingTurn;pendingTurn=null;navigate(queued,false);}if(pendingMode!==null){const queued=pendingMode;pendingMode=null;switchMode(queued);}return;}
const frontPage=forward?oldPages[1]:oldPages[0];const backPage=forward?nextPages[0]:nextPages[1];const flip=document.createElement('div');flip.className='page-turn'+(forward?'':' backward');flip.innerHTML=`<div class="flip-face front"><img alt="" src="${imgSrc(frontPage)}"></div><div class="flip-face back"><img alt="" src="${imgSrc(backPage)}"></div>`;
// Keep the opposite leaf in place while the turning leaf reveals the next spread.
$('spread').replaceChildren(pageElement(forward?oldPages[0]:nextPages[0],'left'),pageElement(forward?nextPages[1]:oldPages[1],'right'));
$('book').append(flip);const imgs=[...flip.querySelectorAll('img')];await Promise.allSettled(imgs.map(img=>img.decode()));
const animation=flip.animate([{transform:'rotateY(0deg)'},{transform:`rotateY(${forward?-180:180}deg)`}],{duration:650,easing:'cubic-bezier(.45,.05,.28,1)',fill:'forwards'});
try{await animation.finished;}catch{}flip.remove();current=target;turning=false;renderSpread();save();setHash();
if(pendingTurn!==null){const queued=pendingTurn;pendingTurn=null;navigate(queued,false);}if(pendingMode!==null){const queued=pendingMode;pendingMode=null;switchMode(queued);} }
function navigate(n,animate=false){n=normalizePage(n);if(turning){pendingTurn=n;return;}if(!reading){enterReader(n);return;}if(mode==='scroll'){current=n;updateMeta();save();setHash();scrollToPage(n);return;}if(animate&&spreadStart(n)!==spreadStart(current)){flipTo(n);return;}current=n;renderSpread();save();setHash();}
function step(dir){if(turning||!reading)return;if(mode==='scroll'){navigate(current+dir,false);return;}const pages=visiblePages();const target=dir>0?pages.at(-1)+1:(pages[0]===2?1:pages[0]-(media.matches?1:2));if(target<1||target>TOTAL)return;navigate(target,true);}
function enterReader(n=savedPage>1?savedPage:2){reading=true;current=normalizePage(n);document.body.classList.add('is-reading');$('coverView').hidden=true;$('coverBottom').hidden=true;$('readerView').hidden=false;renderSpread();save();setHash();if(mode==='scroll'){buildScroll();scrollToPage(current);}}
function home(){if(turning)return;save();reading=false;document.body.classList.remove('is-reading','focus-mode');$('readerView').hidden=true;$('coverView').hidden=false;$('coverBottom').hidden=false;updateCover();try{history.replaceState(null,'',location.pathname+location.search);}catch{}}
function buildScroll(){if(scrollBuilt)return;const frag=document.createDocumentFragment();for(let p=1;p<=TOTAL;p++){const el=document.createElement('article');el.className='scroll-page';el.id='scroll-page-'+p;el.dataset.page=p;const img=document.createElement('img');img.src=imgSrc(p);img.alt=`《奶蛙学》第 ${p} 页 · ${chapterFor(p)}`;img.loading='lazy';img.decoding='async';img.width=1429;img.height=2021;img.draggable=false;el.append(img);const sr=document.createElement('div');sr.className='sr-only';sr.textContent=DATA.texts[p-1]||'';el.append(sr);addLinks(el,p);const badge=document.createElement('span');badge.className='page-badge';badge.textContent=p;el.append(badge);el.addEventListener('click',()=>openZoom(p));frag.append(el);}$('scrollReader').append(frag);scrollBuilt=true;}
function scrollToPage(p){scrollLock=true;requestAnimationFrame(()=>{const el=$('scroll-page-'+p);if(el)$('scrollReader').scrollTo({top:el.offsetTop-$('scrollReader').offsetTop-16,behavior:'instant'});requestAnimationFrame(()=>{scrollLock=false;});});}
let pendingMode=null;
function switchMode(next){if(turning){pendingMode=next;return;}mode=next;$('bookStage').hidden=mode!=='flip';$('scrollReader').hidden=mode!=='scroll';$('readerBottom').classList.toggle('scroll-bottom',mode==='scroll');$('flipMode').classList.toggle('active',mode==='flip');$('scrollMode').classList.toggle('active',mode==='scroll');$('flipMode').setAttribute('aria-pressed',String(mode==='flip'));$('scrollMode').setAttribute('aria-pressed',String(mode==='scroll'));if(mode==='scroll'){buildScroll();scrollToPage(current);}else renderSpread();updateMeta();}
$('scrollReader').addEventListener('scroll',()=>{if(scrollLock||!reading||mode!=='scroll'||scrollRaf)return;scrollRaf=requestAnimationFrame(()=>{scrollRaf=0;const root=$('scrollReader'),rootTop=root.getBoundingClientRect().top;const probe=rootTop+Math.min(root.clientHeight*.3,180);let candidate=1;for(const el of root.children){if(el.getBoundingClientRect().top<=probe)candidate=Number(el.dataset.page);else break;}if(candidate!==current){current=candidate;updateMeta();save();setHash();}});},{passive:true});
function toggleBookmark(){if(bookmarks.has(current)){bookmarks.delete(current);toast('已移除这一页的书签');}else{bookmarks.add(current);toast(`已在第 ${current} 页夹入书签`);}save();updateMeta();renderBookmarks();}
function renderBookmarks(){$('bookmarkCount').textContent=bookmarks.size+' 枚';const list=$('bookmarkList');list.replaceChildren();if(!bookmarks.size){list.innerHTML='<p class="empty-state">还没有夹入书签。<br>遇到喜欢的内容，点一下书签图标。</p>';return;}for(const p of [...bookmarks].sort((a,b)=>a-b)){const row=document.createElement('div');row.className='bookmark-item';const btn=document.createElement('button');btn.className='toc-item';btn.innerHTML=`<span>${escapeHtml(chapterFor(p))}</span><span class="num">${p}</span>`;btn.addEventListener('click',()=>{$('drawer').close();navigate(p);});const del=document.createElement('button');del.className='delete';del.setAttribute('aria-label',`删除第 ${p} 页书签`);del.innerHTML='<svg><use href="#i-trash"/></svg>';del.addEventListener('click',()=>{bookmarks.delete(p);save();updateMeta();renderBookmarks();});row.append(btn,del);list.append(row);}}
function renderToc(){const frag=document.createDocumentFragment();for(const t of DATA.toc){const b=document.createElement('button');b.className='toc-item'+(t.depth?' sub':'')+(t.title.match(/^第.+章/)?' chapter':'');b.dataset.page=t.page;b.innerHTML=`<span>${escapeHtml(t.title)}</span><span class="num">${t.page}</span>`;b.addEventListener('click',()=>{$('drawer').close();navigate(t.page);});frag.append(b);}$('tocList').append(frag);}
function setTab(tab){document.querySelectorAll('[data-tab]').forEach(b=>{b.setAttribute('aria-selected',String(b.dataset.tab===tab));b.tabIndex=b.dataset.tab===tab?0:-1;});for(const t of ['toc','search','marks'])$('pane-'+t).hidden=t!==tab;if(tab==='search')requestAnimationFrame(()=>$('searchInput').focus());if(tab==='marks')renderBookmarks();}
function openDrawer(tab){updateMeta();setTab(tab);if(!$('drawer').open)$('drawer').showModal();if(tab==='search')$('searchInput').focus();}
const cleanTexts=DATA.texts.map(t=>t.replace(/([\p{Script=Han}])\s+(?=[\p{Script=Han}])/gu,'$1').replace(/\s+/g,' ').trim());
function search(){const query=$('searchInput').value.trim(),results=$('searchResults');results.replaceChildren();if(!query){$('searchSummary').textContent='输入关键词，查找全书内容';return;}const terms=query.toLocaleLowerCase().split(/\s+/).filter(Boolean);const matches=[];cleanTexts.forEach((text,i)=>{const lower=text.toLocaleLowerCase();if(terms.every(t=>lower.includes(t)))matches.push({page:i+1,text,index:lower.indexOf(terms[0])});});$('searchSummary').textContent=matches.length?`找到 ${matches.length} 个相关书页`:'没有找到相关内容，试试更短的关键词';for(const match of matches){const b=document.createElement('button');b.className='search-result';const start=Math.max(0,match.index-32),end=Math.min(match.text.length,match.index+110);const snippet=match.text.slice(start,end);let html='';let i=0;const lower=snippet.toLocaleLowerCase();while(i<snippet.length){const term=terms.find(t=>lower.startsWith(t,i));if(term){html+='<mark>'+escapeHtml(snippet.slice(i,i+term.length))+'</mark>';i+=term.length;}else html+=escapeHtml(snippet[i++]);}b.innerHTML=`<strong>第 ${match.page} 页 · ${escapeHtml(chapterFor(match.page))}</strong><p>${start?'…':''}${html}${end<match.text.length?'…':''}</p>`;b.addEventListener('click',()=>{$('drawer').close();navigate(match.page);});results.append(b);}}
let searchTimer=0;$('searchInput').addEventListener('input',()=>{clearTimeout(searchTimer);searchTimer=setTimeout(search,140);});
function applyZoom(){const pad=media.matches?24:48;const width=($('zoomBody').clientWidth-pad)*zoomScale;$('zoomImage').style.width=width+'px';$('zoomLevel').textContent=Math.round(zoomScale*100)+'%';$('zoomOut').disabled=zoomScale<=.75;$('zoomIn').disabled=zoomScale>=3;}
function openZoom(p){zoomPage=p;zoomScale=1;$('zoomImage').src=imgSrc(p);$('zoomImage').alt=`《奶蛙学》第 ${p} 页放大图`;$('zoomTitle').textContent=`第 ${p} 页 / ${TOTAL}`;$('zoomDialog').showModal();applyZoom();$('zoomBody').scrollTo(0,0);}
function focusMode(force){const enabled=typeof force==='boolean'?force:!document.body.classList.contains('focus-mode');document.body.classList.toggle('focus-mode',enabled);requestAnimationFrame(fitBook);}
$('coverImage').src=imgSrc(1);
$('startBtn').addEventListener('click',()=>enterReader());$('coverBook').addEventListener('click',()=>enterReader());$('coverBook').addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();enterReader();}});$('homeBtn').addEventListener('click',home);$('prevBtn').addEventListener('click',()=>step(-1));$('nextBtn').addEventListener('click',()=>step(1));$('flipMode').addEventListener('click',()=>switchMode('flip'));$('scrollMode').addEventListener('click',()=>switchMode('scroll'));$('markBtn').addEventListener('click',toggleBookmark);$('readRibbon').addEventListener('click',toggleBookmark);$('drawerMarkBtn').addEventListener('click',toggleBookmark);$('zoomBtn').addEventListener('click',()=>openZoom(current));$('focusBtn').addEventListener('click',()=>focusMode());$('exitFocus').addEventListener('click',()=>focusMode(false));$('progress').addEventListener('input',()=>{$('percent').textContent=Math.round(Number($('progress').value)/TOTAL*100)+'%';});$('progress').addEventListener('change',()=>navigate($('progress').value));$('jumpForm').addEventListener('submit',e=>{e.preventDefault();if(!$('pageInput').checkValidity())return;navigate($('pageInput').value);$('pageInput').blur();});document.querySelectorAll('[data-drawer]').forEach(b=>b.addEventListener('click',()=>openDrawer(b.dataset.drawer)));document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>setTab(b.dataset.tab)));$('closeDrawer').addEventListener('click',()=>$('drawer').close());$('zoomClose').addEventListener('click',()=>$('zoomDialog').close());$('zoomIn').addEventListener('click',()=>{zoomScale=Math.min(3,zoomScale+.25);applyZoom();});$('zoomOut').addEventListener('click',()=>{zoomScale=Math.max(.75,zoomScale-.25);applyZoom();});$('zoomReset').addEventListener('click',()=>{zoomScale=1;applyZoom();});$('helpBtn').addEventListener('click',()=>$('helpDialog').showModal());$('helpClose').addEventListener('click',()=>$('helpDialog').close());
for(const id of ['drawer','helpDialog'])$(id).addEventListener('click',e=>{if(e.target===$(id)){const r=$(id).getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$(id).close();}});
document.querySelector('.drawer-tabs').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const tabs=[...document.querySelectorAll('[data-tab]')],idx=tabs.findIndex(b=>b.getAttribute('aria-selected')==='true');const next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(idx+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;setTab(tabs[next].dataset.tab);tabs[next].focus();});
document.addEventListener('keydown',e=>{if(e.metaKey||e.ctrlKey||e.altKey)return;const typing=e.target.matches('input,textarea,[contenteditable=true]');if(document.querySelector('dialog[open]'))return;if(typing)return;if(e.key==='Escape'){focusMode(false);return;}if(e.key.toLowerCase()==='c'){e.preventDefault();openDrawer('toc');return;}if(!reading)return;if(e.key==='ArrowRight'||e.key==='PageDown'){e.preventDefault();step(1);}else if(e.key==='ArrowLeft'||e.key==='PageUp'){e.preventDefault();step(-1);}else if(e.key.toLowerCase()==='b'){e.preventDefault();toggleBookmark();}else if(e.key==='Home'){e.preventDefault();navigate(1);}else if(e.key==='End'){e.preventDefault();navigate(TOTAL);}});
let pointerStart=null,suppressClick=false;$('bookStage').addEventListener('pointerdown',e=>{if(e.pointerType==='touch'&&!e.target.closest('button,a'))pointerStart={x:e.clientX,y:e.clientY};});$('bookStage').addEventListener('pointerup',e=>{if(!pointerStart)return;const dx=e.clientX-pointerStart.x,dy=e.clientY-pointerStart.y;pointerStart=null;if(Math.abs(dx)>45&&Math.abs(dx)>Math.abs(dy)*1.3){suppressClick=true;step(dx<0?1:-1);setTimeout(()=>suppressClick=false,350);}});$('bookStage').addEventListener('pointercancel',()=>pointerStart=null);
window.addEventListener('resize',()=>{cancelAnimationFrame(resizeRaf);resizeRaf=requestAnimationFrame(()=>{fitBook();if($('zoomDialog').open)applyZoom();});});media.addEventListener('change',()=>{if(reading&&mode==='flip'){if(turning){pendingTurn=current;}else renderSpread();}});window.addEventListener('hashchange',()=>{const m=location.hash.match(/^#page=(\d+)$/);if(m)navigate(Number(m[1]));});
renderToc();updateCover();renderBookmarks();const initial=location.hash.match(/^#page=(\d+)$/);if(initial)enterReader(Number(initial[1]));

